              >
                <Sparkles className="w-3.5 h-3.5 shrink-0" />
                <span>{suggestion}</span>
              </button>
            ))}
          </div>
        )}

        {/* Reply / Reply All / Forward Buttons OR Inline Composer */}
        {!replyMode ? (
