  console.log("Sent message visible in Sent folder:", sentVisible);

  // Reset demo data so initial state is clean
  await page.getByLabel("Account controls").click();
  await page.getByText("Reset Demo Mailbox to Initial Seed").click();

  // Test Mobile Viewport
  await page.setViewportSize({ width: 390, height: 844 });
  await page.getByLabel("Main menu").click();
  await page.waitForTimeout(150);

  await browser.close();
  if (errors.length > 0) {
    console.error("Console/Page errors:", errors);
    process.exit(1);
  }
  console.log("ALL E2E CHECKS PASSED WITH ZERO ERRORS!");
})();
